import subprocess,json,datetime,pathlib,uuid
name='billboard-p04-fixed-copy-'+uuid.uuid4().hex[:8]
image='docker.io/library/node@sha256:f22d6a1f082c02f292e86929b5b0442ac2e5eaf438a5dea9b1566601c3e05940'
record={'recordedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'containerName':name,'commands':[]}
def call(args, archive=None):
    try:
        if archive:
            with open(archive,'rb') as stream:r=subprocess.run(['docker']+args,stdin=stream,capture_output=True,text=True,timeout=60)
        else:r=subprocess.run(['docker']+args,capture_output=True,text=True,timeout=60)
        item={'command':['docker']+args,'exitCode':r.returncode,'stdout':r.stdout,'stderr':r.stderr}
    except subprocess.TimeoutExpired:item={'command':['docker']+args,'timedOut':True,'exitCode':None}
    record['commands'].append(item);return item
code="""import os,json,pathlib,hashlib,uuid
root=pathlib.Path('/work');inv=json.loads((root/'clean-source-inventory.json').read_text())
assert os.getuid()==0 and os.getgid()==0
