for name in ['.build/toolchain','.build/crs-cache','billboard/target','billboard/portal/cache']:
 p=root/name;missing=[];current=p
 while not current.exists():missing.append(current);current=current.parent
 p.mkdir(parents=True,exist_ok=True);created.extend(reversed(missing));paths.add(p)
results=[]
try:
 for p in sorted(paths):
  s=p.stat();assert s.st_uid==0 and s.st_gid==0,str(p)
  probe=p/('ownership-write-probe-'+uuid.uuid4().hex)
