   with probe.open('xb') as stream:stream.write(b'probe')
  finally:probe.unlink(missing_ok=True)
  results.append({'path':str(p),'uid':s.st_uid,'gid':s.st_gid,'mode':oct(s.st_mode & 0o777),'write':'pass'})
finally:
 for p in sorted(set(created),key=lambda x:len(x.parts),reverse=True):p.rmdir()
assert all(not p.exists() for p in created)
print(json.dumps({'effectiveUid':os.getuid(),'effectiveGid':os.getgid(),'verifiedSourceFiles':len(inv['sourceInputs']),'verifiedSymlinks':len(inv['sourceSymlinks']),'directoryChecks':results,'createdProbeDirectoriesRemoved':all(not p.exists() for p in created)}))
"""
